def histogram(test):
    """Given a string representing space-separated lowercase letters, return a dictionary
    of the letter(s) with the most repetition and their corresponding counts."""

    # Handle edge case: empty string
    if not test.strip():
        return {}

    # Step 1: Split the string into letters
    letters = test.split()

    # Step 2: Count occurrences of each letter
    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1

    # Step 3: Find the maximum frequency
    max_count = max(counts.values(), default=0)

    # Step 4: Filter letters with the maximum frequency
    result = {letter: count for letter, count in counts.items() if count == max_count}

    # Step 5: Return the result
    return result
```

