def sort_array(arr):
    """
    In this Kata, you have to sort an array of integers according to
    the number of ones in their binary representation in ascending order.
    For similar number of ones, sort based on decimal value.

    Examples:
    >>> sort_array([1, 5, 2, 3, 4]) == [1, 2, 4, 3, 5]
    >>> sort_array([-2, -3, -4, -5, -6]) == [-4, -6, -2, -5, -3]
    >>> sort_array([1, 0, 2, 3, 4]) == [0, 1, 2, 4, 3]
    """
    def count_ones(num):
        """
        Count the number of '1's in the binary representation of a number.
        Handles negative numbers using two's complement representation for 32-bit integers.
        """
        if num >= 0:
            return bin(num).count('1')
        else:
            # Use two's complement for negative numbers to count '1's correctly
            return bin(num & 0xffffffff).count('1')

    return sorted(arr, key=lambda x: (count_ones(x), x))
