def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def parse_number(value):
        """
        Helper function to parse a value into a float.
        Supports strings with ',' or '.' as decimal separators.
        """
        if isinstance(value, str):
            value = value.replace(',', '.')
            try:
                return float(value)
            except ValueError:
                return None
        return value

    a_parsed = parse_number(a)
    b_parsed = parse_number(b)

    if a_parsed is not None and b_parsed is not None:
        # Both are numeric values, compare them numerically
        if a_parsed > b_parsed:
            return a
        elif b_parsed > a_parsed:
            return b
        else:
            return None
    else:
        # If either value can't be parsed as a number, compare as strings
        if str(a) > str(b):
            return a
        elif str(b) > str(a):
            return b
        else:
            return None
